@Test
public void readLocalWriteHDFS() throws Exception {
    // Initialize table and filesystem
    HoodieTableMetaClient.withPropertyBuilder().setTableType(tableType).setTableName(tableName).setPayloadClass(HoodieAvroPayload.class).initTable(hadoopConf, dfsBasePath);
    // Create write client to write some records in
    HoodieWriteConfig cfg = getHoodieWriteConfig(dfsBasePath);
    HoodieWriteConfig localConfig = getHoodieWriteConfig(tablePath);
    try (SparkRDDWriteClient hdfsWriteClient = getHoodieWriteClient(cfg);
        SparkRDDWriteClient localWriteClient = getHoodieWriteClient(localConfig)) {
        // Write generated data to hdfs (only inserts)
        String readCommitTime = hdfsWriteClient.startCommit();
        LOG.info("Starting commit " + readCommitTime);
        List<HoodieRecord> records = dataGen.generateInserts(readCommitTime, 100);
        JavaRDD<HoodieRecord> writeRecords = jsc.parallelize(records, 1);
        hdfsWriteClient.upsert(writeRecords, readCommitTime);
        // Read from hdfs
        FileSystem fs = FSUtils.getFs(dfsBasePath, HoodieTestUtils.getDefaultHadoopConf());
        HoodieTableMetaClient metaClient = HoodieTableMetaClient.builder().setConf(fs.getConf()).setBasePath(dfsBasePath).build();
        HoodieTimeline timeline = new HoodieActiveTimeline(metaClient).getCommitTimeline();
        Dataset<Row> readRecords = HoodieClientTestUtils.readCommit(dfsBasePath, sqlContext, timeline, readCommitTime);
        assertEquals(readRecords.count(), records.size(), "Should contain 100 records");
        // Write to local
        HoodieTableMetaClient.withPropertyBuilder().setTableType(tableType).setTableName(tableName).setPayloadClass(HoodieAvroPayload.class).initTable(hadoopConf, tablePath);
        String writeCommitTime = localWriteClient.startCommit();
        LOG.info("Starting write commit " + writeCommitTime);
        List<HoodieRecord> localRecords = dataGen.generateInserts(writeCommitTime, 100);
        JavaRDD<HoodieRecord> localWriteRecords = jsc.parallelize(localRecords, 1);
        LOG.info("Writing to path: " + tablePath);
        localWriteClient.upsert(localWriteRecords, writeCommitTime);
        LOG.info("Reading from path: " + tablePath);
        fs = FSUtils.getFs(tablePath, HoodieTestUtils.getDefaultHadoopConf());
        metaClient = HoodieTableMetaClient.builder().setConf(fs.getConf()).setBasePath(tablePath).build();
        timeline = new HoodieActiveTimeline(metaClient).getCommitTimeline();
        Dataset<Row> localReadRecords = HoodieClientTestUtils.readCommit(tablePath, sqlContext, timeline, writeCommitTime);
        assertEquals(localReadRecords.count(), localRecords.size(), "Should contain 100 records");
    }
}

@Test
public void testSchemaCompatibilityBasic() throws Exception {
    assertTrue(TableSchemaResolver.isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, TRIP_EXAMPLE_SCHEMA), "Same schema is compatible");
    String reorderedSchema = TRIP_SCHEMA_PREFIX + EXTRA_TYPE_SCHEMA + TIP_NESTED_SCHEMA + FARE_NESTED_SCHEMA + MAP_TYPE_SCHEMA + TRIP_SCHEMA_SUFFIX;
    assertTrue(TableSchemaResolver.isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, reorderedSchema), "Reordered fields are compatible");
    assertTrue(TableSchemaResolver.isSchemaCompatible(reorderedSchema, TRIP_EXAMPLE_SCHEMA), "Reordered fields are compatible");
    String renamedSchema = TRIP_EXAMPLE_SCHEMA.replace("tip_history", "tip_future");
    assertFalse(TableSchemaResolver.isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, renamedSchema), "Renamed fields are not compatible");
    assertFalse(TableSchemaResolver.isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, TRIP_EXAMPLE_SCHEMA_DEVOLVED), "Deleted single field is not compatible");
    String deletedMultipleFieldSchema = TRIP_SCHEMA_PREFIX + TIP_NESTED_SCHEMA + TRIP_SCHEMA_SUFFIX;
    assertFalse(TableSchemaResolver.isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, deletedMultipleFieldSchema), "Deleted multiple fields are not compatible");
    String renamedRecordSchema = TRIP_EXAMPLE_SCHEMA.replace("triprec", "triprec_renamed");
    assertFalse(TableSchemaResolver.isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, renamedRecordSchema), "Renamed record name is not compatible");
    String swappedFieldSchema = TRIP_SCHEMA_PREFIX + MAP_TYPE_SCHEMA.replace("city_to_state", "fare") + FARE_NESTED_SCHEMA.replace("fare", "city_to_state") + TIP_NESTED_SCHEMA + TRIP_SCHEMA_SUFFIX;
    assertFalse(TableSchemaResolver.isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, swappedFieldSchema), "Swapped fields are not compatible");
    String typeChangeSchemaDisallowed = TRIP_SCHEMA_PREFIX + MAP_TYPE_SCHEMA + FARE_NESTED_SCHEMA + TIP_NESTED_SCHEMA.replace("string", "boolean") + TRIP_SCHEMA_SUFFIX;
    assertFalse(TableSchemaResolver.isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, typeChangeSchemaDisallowed), "Incompatible field type change is not allowed");
    // Array of allowed schema field type transitions
    String[][] allowedFieldChanges = { { "string", "bytes" }, { "bytes", "string" }, { "int", "long" }, { "int", "float" }, { "long", "float" }, { "int", "double" }, { "float", "double" }, { "long", "double" } };
    for (String[] fieldChange : allowedFieldChanges) {
        String fromSchema = TRIP_SCHEMA_PREFIX + EXTRA_FIELD_SCHEMA.replace("string", fieldChange[0]) + TRIP_SCHEMA_SUFFIX;
        String toSchema = TRIP_SCHEMA_PREFIX + EXTRA_FIELD_SCHEMA.replace("string", fieldChange[1]) + TRIP_SCHEMA_SUFFIX;
        assertTrue(TableSchemaResolver.isSchemaCompatible(fromSchema, toSchema), "Compatible field type change is not allowed");
        if (!fieldChange[0].equals("byte") && fieldChange[1].equals("byte")) {
            assertFalse(TableSchemaResolver.isSchemaCompatible(toSchema, fromSchema), "Incompatible field type change is allowed");
        }
    }
    // Names and aliases should match
    String fromSchema = TRIP_SCHEMA_PREFIX + EXTRA_FIELD_SCHEMA + TRIP_SCHEMA_SUFFIX;
    String toSchema = TRIP_SCHEMA_PREFIX.replace("triprec", "new_triprec") + EXTRA_FIELD_SCHEMA + TRIP_SCHEMA_SUFFIX;
    assertFalse(TableSchemaResolver.isSchemaCompatible(fromSchema, toSchema), "Field names should match");
    assertFalse(TableSchemaResolver.isSchemaCompatible(toSchema, fromSchema), "Field names should match");
    assertTrue(TableSchemaResolver.isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, TRIP_EXAMPLE_SCHEMA_EVOLVED), "Added field with default is compatible (Evolved Schema)");
    String multipleAddedFieldSchema = TRIP_SCHEMA_PREFIX + EXTRA_TYPE_SCHEMA + MAP_TYPE_SCHEMA + FARE_NESTED_SCHEMA + TIP_NESTED_SCHEMA + EXTRA_FIELD_SCHEMA + EXTRA_FIELD_SCHEMA.replace("new_field", "new_new_field") + TRIP_SCHEMA_SUFFIX;
    assertTrue(TableSchemaResolver.isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, multipleAddedFieldSchema), "Multiple added fields with defauls are compatible");
    assertFalse(TableSchemaResolver.isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, TRIP_SCHEMA_PREFIX + EXTRA_TYPE_SCHEMA + MAP_TYPE_SCHEMA + FARE_NESTED_SCHEMA + TIP_NESTED_SCHEMA + EXTRA_FIELD_WITHOUT_DEFAULT_SCHEMA + TRIP_SCHEMA_SUFFIX), "Added field without default and not nullable is not compatible (Evolved Schema)");
    assertTrue(TableSchemaResolver.isSchemaCompatible(TRIP_EXAMPLE_SCHEMA, TRIP_SCHEMA_PREFIX + EXTRA_TYPE_SCHEMA + MAP_TYPE_SCHEMA + FARE_NESTED_SCHEMA + TIP_NESTED_SCHEMA + TRIP_SCHEMA_SUFFIX + EXTRA_FIELD_NULLABLE_SCHEMA), "Added nullable field is compatible (Evolved Schema)");
}

@Test
public void testMORTable() throws Exception {
    tableType = HoodieTableType.MERGE_ON_READ;
    // Create the table
    HoodieTableMetaClient.withPropertyBuilder().fromMetaClient(metaClient).setTableType(HoodieTableType.MERGE_ON_READ).setTimelineLayoutVersion(VERSION_1).initTable(metaClient.getHadoopConf(), metaClient.getBasePath());
    HoodieWriteConfig hoodieWriteConfig = getWriteConfig(TRIP_EXAMPLE_SCHEMA);
    SparkRDDWriteClient client = getHoodieWriteClient(hoodieWriteConfig);
    // Initial inserts with TRIP_EXAMPLE_SCHEMA
    int numRecords = 10;
    insertFirstBatch(hoodieWriteConfig, client, "001", initCommitTime, numRecords, SparkRDDWriteClient::insert, false, false, numRecords);
    checkLatestDeltaCommit("001");
    // Compact once so we can incrementally read later
    assertTrue(client.scheduleCompactionAtInstant("002", Option.empty()));
    client.compact("002");
    // Updates with same schema is allowed
    final int numUpdateRecords = 5;
    updateBatch(hoodieWriteConfig, client, "003", "002", Option.empty(), initCommitTime, numUpdateRecords, SparkRDDWriteClient::upsert, false, false, 0, 0, 0);
    checkLatestDeltaCommit("003");
    checkReadRecords("000", numRecords);
    // Delete with same schema is allowed
    final int numDeleteRecords = 2;
    numRecords -= numDeleteRecords;
    deleteBatch(hoodieWriteConfig, client, "004", "003", initCommitTime, numDeleteRecords, SparkRDDWriteClient::delete, false, false, 0, 0);
    checkLatestDeltaCommit("004");
    checkReadRecords("000", numRecords);
    // Insert with evolved schema is not allowed
    HoodieWriteConfig hoodieDevolvedWriteConfig = getWriteConfig(TRIP_EXAMPLE_SCHEMA_DEVOLVED);
    client = getHoodieWriteClient(hoodieDevolvedWriteConfig);
    final List<HoodieRecord> failedRecords = generateInsertsWithSchema("004", numRecords, TRIP_EXAMPLE_SCHEMA_DEVOLVED);
    try {
        // We cannot use insertBatch directly here because we want to insert records
        // with a devolved schema and insertBatch inserts records using the TRIP_EXMPLE_SCHEMA.
        writeBatch(client, "005", "004", Option.empty(), "003", numRecords, (String s, Integer a) -> failedRecords, SparkRDDWriteClient::insert, false, 0, 0, 0, false);
        fail("Insert with devolved scheme should fail");
    } catch (HoodieInsertException ex) {
        // no new commit
        checkLatestDeltaCommit("004");
        checkReadRecords("000", numRecords);
        client.rollback("005");
    }
    // Update with devolved schema is also not allowed
    try {
        updateBatch(hoodieDevolvedWriteConfig, client, "005", "004", Option.empty(), initCommitTime, numUpdateRecords, SparkRDDWriteClient::upsert, false, false, 0, 0, 0);
        fail("Update with devolved scheme should fail");
    } catch (HoodieUpsertException ex) {
        // no new commit
        checkLatestDeltaCommit("004");
        checkReadRecords("000", numRecords);
        client.rollback("005");
    }
    // Insert with an evolved scheme is allowed
    HoodieWriteConfig hoodieEvolvedWriteConfig = getWriteConfig(TRIP_EXAMPLE_SCHEMA_EVOLVED);
    client = getHoodieWriteClient(hoodieEvolvedWriteConfig);
    // We cannot use insertBatch directly here because we want to insert records
    // with a evolved schemaand insertBatch inserts records using the TRIP_EXMPLE_SCHEMA.
    final List<HoodieRecord> evolvedRecords = generateInsertsWithSchema("005", numRecords, TRIP_EXAMPLE_SCHEMA_EVOLVED);
    writeBatch(client, "005", "004", Option.empty(), initCommitTime, numRecords, (String s, Integer a) -> evolvedRecords, SparkRDDWriteClient::insert, false, 0, 0, 0, false);
    // new commit
    checkLatestDeltaCommit("005");
    checkReadRecords("000", 2 * numRecords);
    // Updates with evolved schema is allowed
    final List<HoodieRecord> updateRecords = generateUpdatesWithSchema("006", numUpdateRecords, TRIP_EXAMPLE_SCHEMA_EVOLVED);
    writeBatch(client, "006", "005", Option.empty(), initCommitTime, numUpdateRecords, (String s, Integer a) -> updateRecords, SparkRDDWriteClient::upsert, false, 0, 0, 0, false);
    // new commit
    checkLatestDeltaCommit("006");
    checkReadRecords("000", 2 * numRecords);
    // Now even the original schema cannot be used for updates as it is devolved in relation to the
    // current schema of the dataset.
    client = getHoodieWriteClient(hoodieWriteConfig);
    try {
        updateBatch(hoodieWriteConfig, client, "007", "006", Option.empty(), initCommitTime, numUpdateRecords, SparkRDDWriteClient::upsert, false, false, 0, 0, 0);
        fail("Update with original scheme should fail");
    } catch (HoodieUpsertException ex) {
        // no new commit
        checkLatestDeltaCommit("006");
        checkReadRecords("000", 2 * numRecords);
        client.rollback("007");
    }
    // Now even the original schema cannot be used for inserts as it is devolved in relation to the
    // current schema of the dataset.
    try {
        // We are not using insertBatch directly here because insertion of these
        // records will fail and we dont want to keep these records within HoodieTestDataGenerator as we
        // will be testing updates later.
        failedRecords.clear();
        failedRecords.addAll(dataGen.generateInserts("007", numRecords));
        writeBatch(client, "007", "006", Option.empty(), initCommitTime, numRecords, (String s, Integer a) -> failedRecords, SparkRDDWriteClient::insert, true, numRecords, numRecords, 1, false);
        fail("Insert with original scheme should fail");
    } catch (HoodieInsertException ex) {
        // no new commit
        checkLatestDeltaCommit("006");
        checkReadRecords("000", 2 * numRecords);
        client.rollback("007");
        // Remove the inserts from the in-memory state of HoodieTestDataGenerator
        // as these records were never inserted in the dataset. This is required so
        // that future calls to updateBatch or deleteBatch do not generate updates
        // or deletes for records which do not even exist.
        for (HoodieRecord record : failedRecords) {
            assertTrue(dataGen.deleteExistingKeyIfPresent(record.getKey()));
        }
    }
    // Rollback to the original schema
    client.restoreToInstant("004");
    checkLatestDeltaCommit("004");
    // Updates with original schema are now allowed
    client = getHoodieWriteClient(hoodieWriteConfig);
    updateBatch(hoodieWriteConfig, client, "008", "004", Option.empty(), initCommitTime, numUpdateRecords, SparkRDDWriteClient::upsert, false, false, 0, 0, 0);
    // new commit
    checkLatestDeltaCommit("008");
    checkReadRecords("000", 2 * numRecords);
    // Insert with original schema is allowed now
    insertBatch(hoodieWriteConfig, client, "009", "008", numRecords, SparkRDDWriteClient::insert, false, false, 0, 0, 0);
    checkLatestDeltaCommit("009");
    checkReadRecords("000", 3 * numRecords);
}

