    String hoodieTableDDL = TestConfigurations.getCreateHoodieTableDDL("t1", options);
    tableEnv.executeSql(hoodieTableDDL);
    String insertInto = "insert into t1 values\n" + "('id1','Danny',23,TIMESTAMP '1970-01-01 00:00:01','par1'),\n" + "('id2','Stephen',33,TIMESTAMP '1970-01-01 00:00:02','par1'),\n" + "('id3','Julian',53,TIMESTAMP '1970-01-01 00:00:03','par2'),\n" + "('id4','Fabian',31,TIMESTAMP '1970-01-01 00:00:04','par2'),\n" + "('id5','Sophia',18,TIMESTAMP '1970-01-01 00:00:05','par3'),\n" + "('id6','Emma',20,TIMESTAMP '1970-01-01 00:00:06','par3'),\n" + "('id7','Bob',44,TIMESTAMP '1970-01-01 00:00:07','par4'),\n" + "('id8','Han',56,TIMESTAMP '1970-01-01 00:00:08','par4')";
    tableEnv.executeSql(insertInto).await();
    // wait for the asynchronous commit to finish
    TimeUnit.SECONDS.sleep(3);
    // Make configuration and setAvroSchema.
    StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    FlinkCompactionConfig cfg = new FlinkCompactionConfig();
    cfg.path = tempFile.getAbsolutePath();
    Configuration conf = FlinkCompactionConfig.toFlinkConfig(cfg);
    conf.setString(FlinkOptions.TABLE_TYPE.key(), "MERGE_ON_READ");
    // create metaClient
    HoodieTableMetaClient metaClient = StreamerUtil.createMetaClient(conf);
    // set the table name
    conf.setString(FlinkOptions.TABLE_NAME, metaClient.getTableConfig().getTableName());
    // set table schema
    CompactionUtil.setAvroSchema(conf, metaClient);
    // judge whether have operation
    // To compute the compaction instant time and do compaction.
    String compactionInstantTime = CompactionUtil.getCompactionInstantTime(metaClient);
    HoodieFlinkWriteClient writeClient = StreamerUtil.createWriteClient(conf, null);
    writeClient.scheduleCompactionAtInstant(compactionInstantTime, Option.empty());
    HoodieFlinkTable<?> table = writeClient.getHoodieTable();
    // generate compaction plan
