    HoodieCompactionPlan compactionPlan = CompactionUtils.getCompactionPlan(table.getMetaClient(), compactionInstantTime);
    HoodieInstant instant = HoodieTimeline.getCompactionRequestedInstant(compactionInstantTime);
    env.addSource(new CompactionPlanSourceFunction(table, instant, compactionPlan, compactionInstantTime)).name("compaction_source").uid("uid_compaction_source").rebalance().transform("compact_task", TypeInformation.of(CompactionCommitEvent.class), new ProcessOperator<>(new CompactFunction(conf))).setParallelism(compactionPlan.getOperations().size()).addSink(new CompactionCommitSink(conf)).name("clean_commits").uid("uid_clean_commits").setParallelism(1);
    env.execute("flink_hudi_compaction");
    TestData.checkWrittenFullData(tempFile, EXPECTED);
}

@Test
public void testMergeOnReadWriteWithCompaction() throws Exception {
    Configuration conf = TestConfigurations.getDefaultConf(tempFile.getAbsolutePath());
    conf.setInteger(FlinkOptions.COMPACTION_DELTA_COMMITS, 1);
    conf.setString(FlinkOptions.TABLE_TYPE, HoodieTableType.MERGE_ON_READ.name());
    StreamExecutionEnvironment execEnv = StreamExecutionEnvironment.getExecutionEnvironment();
    execEnv.getConfig().disableObjectReuse();
    execEnv.setParallelism(4);
    // set up checkpoint interval
    execEnv.enableCheckpointing(4000, CheckpointingMode.EXACTLY_ONCE);
    execEnv.getCheckpointConfig().setMaxConcurrentCheckpoints(1);
    // Read from file source
    RowType rowType = (RowType) AvroSchemaConverter.convertToDataType(StreamerUtil.getSourceSchema(conf)).getLogicalType();
    StreamWriteOperatorFactory<HoodieRecord> operatorFactory = new StreamWriteOperatorFactory<>(conf);
    JsonRowDataDeserializationSchema deserializationSchema = new JsonRowDataDeserializationSchema(rowType, InternalTypeInfo.of(rowType), false, true, TimestampFormat.ISO_8601);
    String sourcePath = Objects.requireNonNull(Thread.currentThread().getContextClassLoader().getResource("test_source.data")).toString();
    TextInputFormat format = new TextInputFormat(new Path(sourcePath));
    format.setFilesFilter(FilePathFilter.createDefaultFilter());
    TypeInformation<String> typeInfo = BasicTypeInfo.STRING_TYPE_INFO;
    format.setCharsetName("UTF-8");
    DataStream<HoodieRecord> hoodieDataStream = execEnv.// use PROCESS_CONTINUOUSLY mode to trigger checkpoint
    readFile(format, sourcePath, FileProcessingMode.PROCESS_CONTINUOUSLY, 1000, typeInfo).map(record -> deserializationSchema.deserialize(record.getBytes(StandardCharsets.UTF_8))).setParallelism(4).map(new RowDataToHoodieFunction<>(rowType, conf), TypeInformation.of(HoodieRecord.class));
    if (conf.getBoolean(FlinkOptions.INDEX_BOOTSTRAP_ENABLED)) {
        hoodieDataStream = hoodieDataStream.transform("index_bootstrap", TypeInformation.of(HoodieRecord.class), new ProcessOperator<>(new BootstrapFunction<>(conf)));
    }
    DataStream<Object> pipeline = hoodieDataStream.// Key-by record key, to avoid multiple subtasks write to a bucket at the same time
    keyBy(HoodieRecord::getRecordKey).transform("bucket_assigner", TypeInformation.of(HoodieRecord.class), new BucketAssignOperator<>(new BucketAssignFunction<>(conf))).uid("uid_bucket_assigner").// shuffle by fileId(bucket id)
    keyBy(record -> record.getCurrentLocation().getFileId()).transform("hoodie_stream_write", TypeInformation.of(Object.class), operatorFactory).uid("uid_hoodie_stream_write");
    pipeline.addSink(new CleanFunction<>(conf)).setParallelism(1).name("clean_commits").uid("uid_clean_commits");
    pipeline.transform("compact_plan_generate", TypeInformation.of(CompactionPlanEvent.class), new CompactionPlanOperator(conf)).uid("uid_compact_plan_generate").setParallelism(// plan generate must be singleton
    1).rebalance().transform("compact_task", TypeInformation.of(CompactionCommitEvent.class), new ProcessOperator<>(new CompactFunction(conf))).addSink(new CompactionCommitSink(conf)).name("compact_commit").setParallelism(1);
    JobClient client = execEnv.executeAsync(execEnv.getStreamGraph(conf.getString(FlinkOptions.TABLE_NAME)));
    if (client.getJobStatus().get() != JobStatus.FAILED) {
        try {
            // wait long enough for the compaction to finish
            TimeUnit.SECONDS.sleep(20);
            client.cancel();
        } catch (Throwable var1) {
            // ignored
        }
    }
    TestData.checkWrittenFullData(tempFile, EXPECTED);
}

