public void testIncrementalFetchFallbackToFullFetchWhenError() {
    PROPS.setProperty("hoodie.deltastreamer.jdbc.incr.pull", "true");
    PROPS.setProperty("hoodie.deltastreamer.jdbc.table.incr.column.name", "last_insert");
    try {
